#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <string.h>

typedef struct {
    float x, y, z;
} Vec3;

typedef struct {
    Vec3 p, n;
    float t;
    int hit;
} Ray;

Vec3 add(Vec3 a, Vec3 b) {
    return (Vec3){a.x + b.x, a.y + b.y, a.z + b.z};
}

Vec3 sub(Vec3 a, Vec3 b) {
    return (Vec3){a.x - b.x, a.y - b.y, a.z - b.z};
}

Vec3 mul(Vec3 a, float f) {
    return (Vec3){a.x * f, a.y * f, a.z * f};
}

float dot(Vec3 a, Vec3 b) {
    return a.x * b.x + a.y * b.y + a.z * b.z;
}

Vec3 norm(Vec3 v) {
    float l = sqrt(dot(v, v));
    return (Vec3){v.x / l, v.y / l, v.z / l};
}

void intersect(Vec3 o, Vec3 d, Vec3 c, float r, Ray *res) {
    Vec3 oc = sub(o, c);
    float a = dot(d, d);
    float b = 2.0 * dot(oc, d);
    float c_val = dot(oc, oc) - r * r;
    float disc = b * b - 4.0 * a * c_val;

    res->hit = 0;
    if (disc < 0) return;

    float t = (-b - sqrt(disc)) / (2.0 * a);
    if (t < 0.0001) t = (-b + sqrt(disc)) / (2.0 * a);
    if (t < 0.0001) return;

    res->hit = 1;
    res->t = t;
    res->p = add(o, mul(d, t));
    res->n = norm(sub(res->p, c));
}

int main() {
    int w = 800, h = 600;
    int size = w * h * 3;
    unsigned char *img = malloc(size);

    printf("Creating high-resolution image: %dx%d\n", w, h);
    printf("This will be downsampled with ffmpeg after rendering\n");
    printf("Rendering high-resolution image...\n");

    Vec3 cam = {0, 1.5, -8};
    Vec3 light = {2, 3, -1};
    Vec3 sphere_pos = {0, 1.5, 0};
    float sphere_r = 1.5;
    Vec3 sky = {0.624, 0.773, 1.0};

    for (int y = 0; y < h; y++) {
        int progress = (y * 100) / h;
        printf("\rProgress: %d.%%", progress);
        fflush(stdout);

        for (int x = 0; x < w; x++) {
            float u = (2.0 * x / w - 1.0) * w / h;
            float v = 1.0 - 2.0 * y / h;

            Vec3 d = norm((Vec3){u, v, 1.0});
            Ray r;
            intersect(cam, d, sphere_pos, sphere_r, &r);

            Vec3 col = sky;
            if (r.hit) {
                Vec3 to_light = norm(sub(light, r.p));
                float diff = fmax(0, dot(r.n, to_light));
                col = (Vec3){0.2 + 0.6 * diff, 0.2 + 0.6 * diff, 0.8 + 0.2 * diff};
            }

            int idx = (y * w + x) * 3;
            img[idx] = (int)(col.x * 255);
            img[idx + 1] = (int)(col.y * 255);
            img[idx + 2] = (int)(col.z * 255);
        }
    }

    printf("\nRendering complete\n");

    FILE *f = fopen("image.ppm", "w");
    fprintf(f, "P3\n%d %d\n255\n", w, h);
    for (int i = 0; i < size; i++) {
        fprintf(f, "%d", img[i]);
        if ((i + 1) % 3 == 0) fprintf(f, "\n");
        else fprintf(f, " ");
    }
    fclose(f);

    printf("Wrote image to image.ppm\n");
    printf("Done.\n");

    return 0;
}
